return {["scripts/items/gargoyle_boots.lua"]={["Path"]="scripts/items/gargoyle_boots.lua",["SHA256"]="2aee65fd1b9439ef8266f05a580f53fc8f7b44f603a9dbf6ebec743666cd36e2",["Text"]="-----------------------------------\n-- ID: 15326\n-- Item: Gargoyle Boots\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local pet = caster:getPet()\n\n    -- No obvious range limit, observed working at 30' (max engaged range)\n    if not pet or (pet and pet:getPetID() ~= xi.petId.WYVERN) then\n        return xi.msg.basic.ITEM_NO_TARGET\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local pet = user:getPet()\n\n    if pet and pet:getPetID() == xi.petId.WYVERN then\n        -- item is self target but reports effect on Wyvern.\n        action:ID(user:getID(), pet:getID())\n\n        if pet:addStatusEffect(xi.effect.STONESKIN, { power = 200, duration = 60, origin = user }) then\n            action:messageID(pet:getID(), xi.msg.basic.ITEM_RECEIVES_EFFECT)\n\n            return xi.effect.STONESKIN\n        end\n    end\n\n    action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Guessed\n\n    return 0\nend\n\nreturn itemObject\n"},["scripts/items/garlic_cracker.lua"]={["Path"]="scripts/items/garlic_cracker.lua",["SHA256"]="fc4b330c716dac69986a4acbc4ee3246e619f5bd73d295979709db633dbfb891",["Text"]="-----------------------------------\n-- ID: 4467\n-- Item: garlic_cracker\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- HP Regen While Healing 6\n-- Undead Killer 10\n-- Blind Resist 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 6)\n    effect:addMod(xi.mod.UNDEAD_KILLER, 10)\n    effect:addMod(xi.mod.BLINDRES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/garlic_cracker_+1.lua"]={["Path"]="scripts/items/garlic_cracker_+1.lua",["SHA256"]="2e2ed1a5097915e2cc85c7e3943260fdaa2ee28220c60b46f445b4ca250f38ab",["Text"]="-----------------------------------\n-- ID: 4280\n-- Item: garlic_cracker_+1\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- HP recovered while healing +8\n-- Undead Killer +12\n-- Blind Resist +12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 8)\n    effect:addMod(xi.mod.UNDEAD_KILLER, 12)\n    effect:addMod(xi.mod.BLINDRES, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/garpike.lua"]={["Path"]="scripts/items/garpike.lua",["SHA256"]="0f0eced80531ef20f08a7b67d17b96429a7de2de9a891daee476dc58c636066e",["Text"]="-----------------------------------\n-- ID: 5472\n-- Item: Garpike\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gashing_bolt_quiver.lua"]={["Path"]="scripts/items/gashing_bolt_quiver.lua",["SHA256"]="16843c1eb4cee6c1b8dff0fce676fefe68970f45da65f576b3ecc9cf004edd87",["Text"]="-----------------------------------\n-- ID: 6310\n-- Item: Gash. Bolt Quiver\n-- When used, you will obtain one stack of Gashing Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.GASHING_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/gastraphetes.lua"]={["Path"]="scripts/items/gastraphetes.lua",["SHA256"]="5be7f769b5a43c8efed00a7367e425f40ee1a052ae51f4b0d26c048aefad24d5",["Text"]="-----------------------------------\n-- ID: 19001\n-- Item: Gastraphetes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getFreeSlotsCount() == 0 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.QUELLING_BOLT, 99 } }) -- Quelling Bolt x99\nend\n\nreturn itemObject\n"},["scripts/items/gateau_aux_fraises.lua"]={["Path"]="scripts/items/gateau_aux_fraises.lua",["SHA256"]="09b6b4dcebc05e9a5c2db36aba26a4c061b328c68278d838ae4b48b8c2fed561",["Text"]="-----------------------------------\n-- ID: 5542\n-- Item: Gateau aux fraises\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP 8\n-- MP 8% Cap 50\n-- Intelligence 1\n-- HP Recovered while healing 1\n-- MP Recovered while healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.FOOD_MPP, 8)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 50)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/geohelix_schema.lua"]={["Path"]="scripts/items/geohelix_schema.lua",["SHA256"]="3ddd6b1186e0e733463d3ff746f5523b49a0cd8a93a2b7b7205b579d75767a31",["Text"]="-----------------------------------\n-- ID: 6045\n-- Geohelix Schema\n-- Teaches the black magic Geohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.GEOHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.GEOHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/geomancer_die.lua"]={["Path"]="scripts/items/geomancer_die.lua",["SHA256"]="b89c76cce6b42fd33c01c44c52df0d35b7fd9b5d69cc08b8944d03250cdd54e3",["Text"]="-----------------------------------\n-- ID: 6368\n-- Geomancer Die\n-- Teaches the job ability Naturalists Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.NATURALISTS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.NATURALISTS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/getsul_ring.lua"]={["Path"]="scripts/items/getsul_ring.lua",["SHA256"]="18a7dc7b9c5ee8e1b7c57fce18757614951ce211b1e55a200b550b8fce4663e3",["Text"]="-----------------------------------\n-- ID: 14681\n-- Item: Getsul Ring\n-- Item Effect: +20% HP\n-- Duration: 10 Minutes\n-- https://wiki.ffo.jp/html/10072.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.GETSUL_RING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.GETSUL_RING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 600, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.GETSUL_RING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPP, 20)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.GETSUL_RING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ghost_cape.lua"]={["Path"]="scripts/items/ghost_cape.lua",["SHA256"]="bad643f98dd4934e95695c732062759dfd921630206a76448c0136bbee8aafe0",["Text"]="-----------------------------------\n-- ID: 16257\n-- Ghost Cape\n-- Enchantment: 60Min, Costume - Ghost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 368, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/gimlet_spear.lua"]={["Path"]="scripts/items/gimlet_spear.lua",["SHA256"]="5800ead3cba0dd5f59cb0db98f5ab3caec984064fc82f70e7843ce62eabf4bad",["Text"]="-----------------------------------\n-- ID: 18117\n-- Item: gimlet_spear\n-- Item Effect: Attack +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.GIMLET_SPEAR) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.GIMLET_SPEAR)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.GIMLET_SPEAR) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.GIMLET_SPEAR })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ginger_cookie.lua"]={["Path"]="scripts/items/ginger_cookie.lua",["SHA256"]="09abc562a348ec29ec0f07bffb6e8ee73f9c686083c9bd0f28a37a536ff2314b",["Text"]="-----------------------------------\n-- ID: 4394\n-- Item: ginger_cookie\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Magic Regen While Healing 5\n-- Plantoid Killer 10\n-- Slow Resist 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 5)\n    effect:addMod(xi.mod.PLANTOID_KILLER, 10)\n    effect:addMod(xi.mod.SLOWRES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/glorious_sword.lua"]={["Path"]="scripts/items/glorious_sword.lua",["SHA256"]="5527422f265a1dfe9a5c74c58883e40f63d79ec35268c971207288258d546743",["Text"]="-----------------------------------\n-- ID: 16938\n-- Item: Glorious Sword\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 5 + utils.clamp(dStat * 0.0926, 0, 5), -- 5% over 54 MND\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/glowing_lamp.lua"]={["Path"]="scripts/items/glowing_lamp.lua",["SHA256"]="0449223c42e8bf891a533021a6275ed8d6c70036adae4df9e2871faaa2dc4cba",["Text"]="-----------------------------------\n-- ID: 5414\n-- Item: Glowing Lamp\n-- Use: Creates a replica of the Glowing Lamp\n-----------------------------------\n---@type TItem\n\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item)\n    return xi.einherjar.onLampCheck(target, item)\nend\n\nitemObject.onItemUse = function(player, target, item)\n    xi.einherjar.onLampUse(player, item)\nend\n\nitemObject.onItemDrop = function(target, item)\n    xi.einherjar.onLampDrop(target, item)\nend\n\nreturn itemObject\n"},["scripts/items/goblin_belt.lua"]={["Path"]="scripts/items/goblin_belt.lua",["SHA256"]="5c3ec4e581dbfdb880195dad386fdc8bc3eb48b248a1be0bb76ee1df1c42b6bc",["Text"]="-----------------------------------\n-- ID: 15929\n-- Goblin Belt\n-- Enchantment: 60Min, Costume - Goblin (dagger)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 673, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/goblin_mushpot.lua"]={["Path"]="scripts/items/goblin_mushpot.lua",["SHA256"]="082e2dc6707e6e6878eb926ce168b5afe61d59fd39020192d1026b7c6207f0ef",["Text"]="-----------------------------------\n-- ID: 4543\n-- Item: goblin_mushpot\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Mind 10\n-- Charisma -5\n-- Poison Resist 4\n-- Blind Resist 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 10)\n    effect:addMod(xi.mod.CHR, -5)\n    effect:addMod(xi.mod.POISONRES, 4)\n    effect:addMod(xi.mod.BLINDRES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/goblin_pie.lua"]={["Path"]="scripts/items/goblin_pie.lua",["SHA256"]="cdcb410dc661d5e65c8aa862eea441f0677e06d48dc9ea2b014afc34712ca022",["Text"]="-----------------------------------\n-- ID: 4539\n-- Item: goblin_pie\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 12\n-- Magic 12\n-- Dexterity -1\n-- Agility 3\n-- Vitality -1\n-- Charisma -5\n-- Defense % 9 (cap 100)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 12)\n    effect:addMod(xi.mod.FOOD_MP, 12)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.CHR, -5)\n    effect:addMod(xi.mod.FOOD_DEFP, 9)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 100)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gold_carp.lua"]={["Path"]="scripts/items/gold_carp.lua",["SHA256"]="8f7c6a644061b3e8ebb76e3eb8d3dbc69dab12885a7ac58853ea8e167c2ee484",["Text"]="-----------------------------------\n-- ID: 4427\n-- Item: gold_carp\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gold_lobster.lua"]={["Path"]="scripts/items/gold_lobster.lua",["SHA256"]="bbdf3ec2417ed16fd2e9c2988faa443036ad58e0d56d92459155745e7f71d2b6",["Text"]="-----------------------------------\n-- ID: 5797\n-- Item: gold_lobster\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 3\n-- Defense % 16 (Cap 50)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_DEFP, 16)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gold_musketeers_uchigatana.lua"]={["Path"]="scripts/items/gold_musketeers_uchigatana.lua",["SHA256"]="de39efbc9fc12665d18a6638508283356b47d023fd53adc5fe97ec986c77dcb0",["Text"]="-----------------------------------\n-- ID: 17807\n-- Item: Gold Musketeer's Uchigatana\n-- Additional effect: Earth damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 3 + utils.clamp(dStat * 10 / 54, 0, 10), -- Linear interp over 54 INT\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.EARTH,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/goldsmiths_belt.lua"]={["Path"]="scripts/items/goldsmiths_belt.lua",["SHA256"]="2a4e41bb2baad3204c79dd5c3fc500f006bea9071bf85a06ab05423858c1601a",["Text"]="-----------------------------------\n-- ID: 15446\n-- Item: Goldsmith's Belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Goldsmithing Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.GOLDSMITHING_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.GOLDSMITHING_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/goshikitenge.lua"]={["Path"]="scripts/items/goshikitenge.lua",["SHA256"]="12a34aaf03722c3ea594de61dde404519bf3b986f4d5fb3c282d4b75723476f9",["Text"]="-----------------------------------\n-- ID: 5725\n-- Goshikitenge\n-- A launcher appears on the ground and fires 2 volleys of airbursts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/grand_knights_arrow.lua"]={["Path"]="scripts/items/grand_knights_arrow.lua",["SHA256"]="9c8efe0c712d7e8bd656a90e9ba706b59c3e8058e4d60fec8e3279a2a6ee81f7",["Text"]="-----------------------------------\n-- ID: 17327\n-- Item: Grand Knights Arrow\n-- Additional effect: Fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 10 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.FIRE,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/grape_daifuku.lua"]={["Path"]="scripts/items/grape_daifuku.lua",["SHA256"]="06693ccbefb755fa786e3ce562c97c68c429268cff5420af704e796fa1b54dd0",["Text"]="-----------------------------------\n-- ID: 6343\n-- Item: grape_daifuku\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- HP + 20 STR + 2 VIT + 3 (Pet & Master)\n-- Accuracy/Ranged Accuracy +10% (cap 80 on master, cap 105 on pet)\n-- Attack/Ranged Attack +11% (cap 50 on master, cap 75 on pet)\n-- Master MAB + 3 , Pet MAB + 14\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_ACCP, 10)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 50)\n    effect:addMod(xi.mod.FOOD_RACCP, 10)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 50)\n    effect:addMod(xi.mod.MATT, 3)\n    target:addPetMod(xi.mod.FOOD_HP, 20)\n    target:addPetMod(xi.mod.STR, 2)\n    target:addPetMod(xi.mod.VIT, 3)\n    target:addPetMod(xi.mod.FOOD_ACCP, 10)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 105)\n    target:addPetMod(xi.mod.FOOD_ATTP, 10)\n    target:addPetMod(xi.mod.FOOD_ATT_CAP, 75)\n    target:addPetMod(xi.mod.FOOD_RACCP, 10)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 105)\n    target:addPetMod(xi.mod.FOOD_RATTP, 10)\n    target:addPetMod(xi.mod.FOOD_RATT_CAP, 75)\n    target:addPetMod(xi.mod.MATT, 14)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 20)\n    target:delPetMod(xi.mod.STR, 2)\n    target:delPetMod(xi.mod.VIT, 3)\n    target:delPetMod(xi.mod.FOOD_ACCP, 10)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 105)\n    target:delPetMod(xi.mod.FOOD_ATTP, 10)\n    target:delPetMod(xi.mod.FOOD_ATT_CAP, 75)\n    target:delPetMod(xi.mod.FOOD_RACCP, 10)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 105)\n    target:delPetMod(xi.mod.FOOD_RATTP, 10)\n    target:delPetMod(xi.mod.FOOD_RATT_CAP, 75)\n    target:delPetMod(xi.mod.MATT, 14)\nend\n\nreturn itemObject\n"},["scripts/items/grape_daifuku_+1.lua"]={["Path"]="scripts/items/grape_daifuku_+1.lua",["SHA256"]="14a837593640fb560bac195b482d96b07c6ee89db865ba6a0d81f6b47086ff76",["Text"]="-----------------------------------\n-- ID: 6344\n-- Item: grape_daifuku+1\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- HP + 30 STR + 3 VIT + 4 (Pet & Master)\n-- Accuracy/Ranged Accuracy +11% (cap 85 on master, cap 110 on pet)\n-- Attack/Ranged Attack +11% (cap 55 on master, cap 80 on pet)\n-- Master MAB + 4 , Pet MAB + 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_ACCP, 11)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 85)\n    effect:addMod(xi.mod.FOOD_ATTP, 11)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 55)\n    effect:addMod(xi.mod.FOOD_RACCP, 11)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 85)\n    effect:addMod(xi.mod.FOOD_RATTP, 11)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 55)\n    effect:addMod(xi.mod.MATT, 4)\n    target:addPetMod(xi.mod.FOOD_HP, 30)\n    target:addPetMod(xi.mod.STR, 3)\n    target:addPetMod(xi.mod.VIT, 4)\n    target:addPetMod(xi.mod.FOOD_ACCP, 11)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 110)\n    target:addPetMod(xi.mod.FOOD_ATTP, 11)\n    target:addPetMod(xi.mod.FOOD_ATT_CAP, 80)\n    target:addPetMod(xi.mod.FOOD_RACCP, 11)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 110)\n    target:addPetMod(xi.mod.FOOD_RATTP, 11)\n    target:addPetMod(xi.mod.FOOD_RATT_CAP, 80)\n    target:addPetMod(xi.mod.MATT, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 30)\n    target:delPetMod(xi.mod.STR, 3)\n    target:delPetMod(xi.mod.VIT, 4)\n    target:delPetMod(xi.mod.FOOD_ACCP, 11)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 110)\n    target:delPetMod(xi.mod.FOOD_ATTP, 11)\n    target:delPetMod(xi.mod.FOOD_ATT_CAP, 80)\n    target:delPetMod(xi.mod.FOOD_RACCP, 11)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 110)\n    target:delPetMod(xi.mod.FOOD_RATTP, 11)\n    target:delPetMod(xi.mod.FOOD_RATT_CAP, 80)\n    target:delPetMod(xi.mod.MATT, 15)\nend\n\nreturn itemObject\n"},["scripts/items/greedie.lua"]={["Path"]="scripts/items/greedie.lua",["SHA256"]="2e609b3f46a314b39939f8fec98ca3a1a3167e90b6d1c823adb6fe7b36cc3b62",["Text"]="-----------------------------------\n-- ID: 4500\n-- Item: greedie\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/green_curry_bun.lua"]={["Path"]="scripts/items/green_curry_bun.lua",["SHA256"]="1b666b987f30e94794d0891ef3fc6b23436417dde4271ed3d3640e8e6ba8d25d",["Text"]="-----------------------------------\n-- ID: 5756\n-- Item: green_curry_bun\n-- Food Effect: 30 min, All Races\n-- https://wiki.ffo.jp/html/17768.html\n-----------------------------------\n-- VIT +1\n-- AGI +2\n-- Ranged Accuracy +5% (cap 25)\n-- DEF +9% (cap 160)\n-- Resist Sleep +3\n-- hHP +2\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nlocal dataTable =\n{\n    [1] = { xi.mod.VIT,            3,   2,   1 },\n    [2] = { xi.mod.AGI,            4,   3,   2 },\n    [3] = { xi.mod.HPHEAL,         6,   4,   2 },\n    [4] = { xi.mod.MPHEAL,         3,   2,   1 },\n    [5] = { xi.mod.FOOD_RACCP,    10,   8,   5 },\n    [6] = { xi.mod.FOOD_RACC_CAP, 25,  25,  25 },\n    [7] = { xi.mod.FOOD_DEFP,     13,  11,   9 },\n    [8] = { xi.mod.FOOD_DEF_CAP, 180, 170, 160 },\n    [9] = { xi.mod.SLEEPRES,       5,   4,   3 }\n}\n\nitemObject.onEffectGain = function(target, effect)\n    for i = 1, #dataTable do\n        -- Get party factor.\n        local partySize = target:getPartySize()\n        local column = 4\n        if partySize >= 4 then\n            column = 2\n        elseif partySize >= 2 then\n            column = 3\n        end\n\n        effect:addMod(dataTable[i][1], dataTable[i][column])\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/green_curry_bun_+1.lua"]={["Path"]="scripts/items/green_curry_bun_+1.lua",["SHA256"]="7bda17964291ae33abb9cc4da9f25554e92ef155536251ff32273a7c0923d289",["Text"]="-----------------------------------\n-- ID: 5762\n-- Item: green_curry_bun_+1\n-- Food Effect: 60 min, All Races\n-----------------------------------\n-- TODO: Group effects\n-- VIT +3\n-- AGI +4\n-- Ranged Accuracy +10% (cap 25)\n-- DEF +13% (cap 180)\n-- Resist Sleep +5\n-- hHP +6\n-- hMP +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.FOOD_RACCP, 10)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 25)\n    effect:addMod(xi.mod.FOOD_DEFP, 13)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 180)\n    effect:addMod(xi.mod.SLEEPRES, 5)\n    effect:addMod(xi.mod.HPHEAL, 6)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/green_drop.lua"]={["Path"]="scripts/items/green_drop.lua",["SHA256"]="2a596455c09d01996b6a049f620aec0b1d97424d0ec0f7c283ff6a6193d7230a",["Text"]="-----------------------------------\n--  ID: 4260\n--  Item: Green Drop\n--  Agility 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.AGI_BOOST, { power = 5, duration = 900, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/green_quiche.lua"]={["Path"]="scripts/items/green_quiche.lua",["SHA256"]="e19cd465a03b5facde201dc9eb259c080f3e60a5a3a3e7c787e095e35c615d78",["Text"]="-----------------------------------\n-- ID: 5170\n-- Item: green_quiche\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 10\n-- Agility 1\n-- Vitality -1\n-- Ranged ACC % 7\n-- Ranged ACC Cap 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.FOOD_RACCP, 7)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/grilled_lik.lua"]={["Path"]="scripts/items/grilled_lik.lua",["SHA256"]="9b0a580a778b324b40bde5557d05a3f7fff54e3151b9ab0bf8b92240d0f8f4e5",["Text"]="-----------------------------------\n-- ID: 5648\n-- Item: Grilled Lik\n-- Food Effect: 60 Mins, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -3\n-- Accuracy +2\n-- Attack +8\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.ACC, 2)\n    effect:addMod(xi.mod.ATT, 8)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/guide_beret.lua"]={["Path"]="scripts/items/guide_beret.lua",["SHA256"]="479eb16418c99e5d7dbef3159b4c4cd29db29deae4a4b8f743004b068c3da702",["Text"]="-----------------------------------\n-- ID: 15199\n-- Item: Guide Beret\n-- Capacity point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.COMMITMENT) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.COMMITMENT\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/gurnard.lua"]={["Path"]="scripts/items/gurnard.lua",["SHA256"]="42a06b1b7ffe0977007f68405fa123074b4273474c84578fe0f4f1dcc0d498af",["Text"]="-----------------------------------\n-- ID: 5132\n-- Item: Gurnard\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gust_claymore.lua"]={["Path"]="scripts/items/gust_claymore.lua",["SHA256"]="c0982f45ddeb0fffe5aa87984322cea2abcfa1057b4d04bc36d8cb97fc5dff53",["Text"]="-----------------------------------\n-- ID: 18366\n-- Item: Gust Claymore\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 22, -- TODO: this weapon has a lower base delay than tested gsword (Gust Tongue). Check proc rate\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/gust_claymore_+1.lua"]={["Path"]="scripts/items/gust_claymore_+1.lua",["SHA256"]="6462816337356b7dfa71520c4f26819e3ef2df48c91004386f79d91959e7dff8",["Text"]="-----------------------------------\n-- ID: 18367\n-- Item: Gust Claymore +1\n-- Additional effect: Wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 22, -- TODO: this weapon has a lower base delay than tested gsword (Gust Tongue). Check proc rate\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/gust_sword.lua"]={["Path"]="scripts/items/gust_sword.lua",["SHA256"]="39dd37f34eebec1ad6a6c49268b1ce3cd540d9a7be0188255f3d57f23a7e957d",["Text"]="-----------------------------------\n-- ID: 18368\n-- Item: Gust Sword\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAddition