Table)\nend\n\nreturn itemObject\n"},["scripts/items/gust_tongue.lua"]={["Path"]="scripts/items/gust_tongue.lua",["SHA256"]="32806a26c0c381538d77e457884270fa9ddae30fa48e21d33f8cef571c719387",["Text"]="-----------------------------------\n-- ID: 18370\n-- Item: Gust Tongue\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 22,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/gust_tongue_+1.lua"]={["Path"]="scripts/items/gust_tongue_+1.lua",["SHA256"]="98027fa2fdc9dcd21b81eb87c91b5d60469d647a99e8d81b3b656032f35a1dee",["Text"]="-----------------------------------\n-- ID: 18371\n-- Item: Gust Tongue +1\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 22,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/gyokuto_obi.lua"]={["Path"]="scripts/items/gyokuto_obi.lua",["SHA256"]="76faef4e9b1aafed1c4d6850d1359ce2f4b75bbd5256fa5bfd374636602ae74c",["Text"]="-----------------------------------\n-- ID: 15860\n-- Gyokuto Obi\n-- Enchantment: 60Min, Costume - Large Rarab\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 335, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/gyudon.lua"]={["Path"]="scripts/items/gyudon.lua",["SHA256"]="f52247e2b4d4582d6b8c2091bb18b70b84690004dfe68910d1cb1ba0f59b1a11",["Text"]="-----------------------------------\n-- ID: 6686\n-- Item: gyudon\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Enmity -5\n-- Double Attack % 5\n-- Weapon Skill Damage % 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ENMITY, -5)\n    effect:addMod(xi.mod.DOUBLE_ATTACK, 5)\n    effect:addMod(xi.mod.ALL_WSDMG_ALL_HITS, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gyudon_+1.lua"]={["Path"]="scripts/items/gyudon_+1.lua",["SHA256"]="0cffa3f7d20b7cac322c770cbd402c7710ffdf2c33805bed00e584faea349c78",["Text"]="-----------------------------------\n-- ID: 6687\n-- Item: gyudon_+1\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Enmity -6\n-- Double Attack % 6\n-- Weapon Skill Damage % 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ENMITY, -6)\n    effect:addMod(xi.mod.DOUBLE_ATTACK, 6)\n    effect:addMod(xi.mod.ALL_WSDMG_ALL_HITS, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hachiya_shuriken_pouch.lua"]={["Path"]="scripts/items/hachiya_shuriken_pouch.lua",["SHA256"]="9d7557011d351bf0e719a883b8e3f3ab31fccaf4ad7fbc39a8ea99ac1a9b55fd",["Text"]="-----------------------------------\n-- ID: 6308\n-- Item: Hac. Sh. Pouch\n-- When used, you will obtain one stack of Hachiya Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HACHIYA_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/hailstorm_schema.lua"]={["Path"]="scripts/items/hailstorm_schema.lua",["SHA256"]="6d4255127486276a98d053d23063bde0bda17a0479d4e6f6a926b3347a8abfe8",["Text"]="-----------------------------------\n-- ID: 6052\n-- Hailstorm Schema\n-- Teaches the white magic Hailstorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.HAILSTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.HAILSTORM)\nend\n\nreturn itemObject\n"},["scripts/items/hallowed_sword.lua"]={["Path"]="scripts/items/hallowed_sword.lua",["SHA256"]="0668bd3625d38d2540aee6b6443c7dda1735b5db255a830e17db98d5597f88df",["Text"]="-----------------------------------\n-- ID: 16550\n-- Item: Hallowed Sword\n-- Additional effect: light damage\n-- Item Effect: Enlight\n-----------------------------------\n---@type TItem\n\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(5, 7),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENLIGHT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HALLOWED_SWORD) ~= nil then\n        target:delStatusEffect(xi.effect.ENLIGHT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HALLOWED_SWORD)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HALLOWED_SWORD) then\n        target:addStatusEffect(xi.effect.ENLIGHT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HALLOWED_SWORD })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n    effect:addMod(xi.mod.ENSPELL, xi.element.LIGHT)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Needed for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/halo_claymore.lua"]={["Path"]="scripts/items/halo_claymore.lua",["SHA256"]="cda99615a2afbcdadcdc029a64a04b9e07d0d05dd6413a0748e92ab3a1913657",["Text"]="-----------------------------------\n--  ID: 13682\n--  Ether Tank\n--  When used, you will obtain one Ether\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/ham_and_cheese_crepe.lua"]={["Path"]="scripts/items/ham_and_cheese_crepe.lua",["SHA256"]="a6b8155177f193b36d7f27bbb658fa765f0bea2037a6ec149b32d0ab33a61d8f",["Text"]="-----------------------------------\n-- ID: 5771\n-- Item: ham_and_cheese_crepe\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- HP +10% (cap 25)\n-- STR +2\n-- VIT +1\n-- Magic Accuracy +10\n-- Magic Defense +3\n-- hHP +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 25)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.MACC, 10)\n    effect:addMod(xi.mod.MDEF, 3)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hamsi.lua"]={["Path"]="scripts/items/hamsi.lua",["SHA256"]="ac40a60cc9fe9a6622ab8be6e183a5d43fa2abe09eb92f8d112fddf755cba2a5",["Text"]="-----------------------------------\n-- ID: 5449\n-- Item: Hamsi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/hanafubuki.lua"]={["Path"]="scripts/items/hanafubuki.lua",["SHA256"]="c93543b187cba2ac33cd764f83205c19a54589cdd81fdd35ce3197ef1357a748",["Text"]="-----------------------------------\n-- ID: 18427\n-- Item: Hanafubuki\n-- Item Effect: TP +100\n-- Durration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/handful_of_bloody_chocolate.lua"]={["Path"]="scripts/items/handful_of_bloody_chocolate.lua",["SHA256"]="46bf6784ae888defc2b071e2732e1275cd3f42ca501c32c59b198a4f3e847f8a",["Text"]="-----------------------------------\n-- ID: 5646\n-- Item: handful_of_bloody_chocolate\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- MP Recovered While Healing 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/handful_of_roasted_almonds.lua"]={["Path"]="scripts/items/handful_of_roasted_almonds.lua",["SHA256"]="5713903726d53ec251a066bfc13c6e988f9923a070a3c018ab0af339f3a09f76",["Text"]="-----------------------------------\n-- ID: 5649\n-- Item: Handful of Roasted Almonds\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- HP 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/handful_of_sunflower_seeds.lua"]={["Path"]="scripts/items/handful_of_sunflower_seeds.lua",["SHA256"]="8ba09a3902bad3c098d650c826c3bfe6ee27aa17b3a49d669ee66c8017f61359",["Text"]="-----------------------------------\n-- ID: 4505\n-- Item: handful_of_sunflower_seeds\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Dexterity -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/happo_shuriken_+1_pouch.lua"]={["Path"]="scripts/items/happo_shuriken_+1_pouch.lua",["SHA256"]="aebf205a1ff08a3c93de49f473686e2d46f520b85399d0a57c818a42b400fc68",["Text"]="-----------------------------------\n-- ID: 6307\n-- Item: Ha. Sh. +1 Pouch\n-- When used, you will obtain one stack of Happo Shurikens +1\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HAPPO_SHURIKEN_P1, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/happo_shuriken_pouch.lua"]={["Path"]="scripts/items/happo_shuriken_pouch.lua",["SHA256"]="5e007b73a48ce4c2964da6d72299095fbcfcb038c4111a6d5814ea776e051e78",["Text"]="-----------------------------------\n-- ID: 6306\n-- Item: Hap. Sh. Pouch\n-- When used, you will obtain one stack of Happo Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.HAPPO_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/hard-boiled_egg.lua"]={["Path"]="scripts/items/hard-boiled_egg.lua",["SHA256"]="b1b5d6a50b4ef9e6ac85d3c940188dfdc9bf66f9b5ce02ec99e15969aa5f8a9d",["Text"]="-----------------------------------\n-- ID: 4409\n-- Item: hard-boiled_egg\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 10\n-- Magic 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/haste_belt.lua"]={["Path"]="scripts/items/haste_belt.lua",["SHA256"]="0aa9a93e017096148c7a06989ef273d7569cd1296008216165b2f48210c6fee1",["Text"]="-----------------------------------\n-- ID: 15290\n-- Item: Haste Belt\n-- Item Effect: Haste +10% (Magic)\n-- Duration: 3 Minutes\n-- Stacks with Haste (spell)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HASTE_BELT) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HASTE_BELT)\n        if effect then\n            effect:resetStartTime()\n            effect:setIcon(xi.effect.HASTE)\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, icon = xi.effect.HASTE, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HASTE_BELT, flag = xi.effectFlag.NO_LOSS_MESSAGE })\n        end\n\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.HASTE)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HASTE_MAGIC, 1000)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HASTE_BELT)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:messageBasic(xi.msg.basic.STATUS_WEARS_OFF, xi.effect.HASTE)\nend\n\nreturn itemObject\n"},["scripts/items/hatchling_shield.lua"]={["Path"]="scripts/items/hatchling_shield.lua",["SHA256"]="dc64dbbad591989c9ae60cf19905b688abf4458bcfda5634ef4084a5356b880f",["Text"]="-----------------------------------\n-- ID: 28652\n-- Item: Hatchling Shield\n-- When used, you will obtain a random number of egg items\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nlocal eggTable =\n{\n    { xi.item.BIRD_EGG,        1,  8, },\n    { xi.item.CRAWLER_EGG,     3,  9, },\n    { xi.item.EMPEROR_ROE,     1, 10, },\n    { xi.item.HARD_BOILED_EGG, 4,  7, },\n    { xi.item.LIZARD_EGG,      2,  9, },\n    { xi.item.SAIRUI_RAN,      1, 10, },\n}\n\nif xi.settings.main.ENABLE_TOAU == 1 then\n    table.insert(eggTable, { xi.item.APKALLU_EGG,        1, 11, })\n    table.insert(eggTable, { xi.item.CHUNK_OF_FLAN_MEAT, 1,  6, })\n    table.insert(eggTable, { xi.item.PUK_EGG,            1,  7, })\n    table.insert(eggTable, { xi.item.SALMON_EGGS,        3,  7, })\nend\n\nitemObject.onItemUse = function(target)\n    local egg = eggTable[math.randomInt(1, #eggTable)]\n    npcUtil.giveItem(target, { { egg[1], math.randomInt(egg[2], egg[3]) } })\nend\n\nreturn itemObject\n"},["scripts/items/hauteclaire.lua"]={["Path"]="scripts/items/hauteclaire.lua",["SHA256"]="ffa84068d823b5d8f89991fca40e89c5407e8de1c802f89d4c52e999e17e56c3",["Text"]="-----------------------------------\n-- ID: 17738\n-- Item: Hauteclaire\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 24, -- TODO: something can make this increase up to 55% but testing was inconclusive. it may be dlvl.\n        basePower      = math.randomInt(11, 15),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/head_of_grauberg_lettuce.lua"]={["Path"]="scripts/items/head_of_grauberg_lettuce.lua",["SHA256"]="7436f7f0c13aaad325c2db1ec32d313639f290ac5bff94c0ac14eae6a60ad9c2",["Text"]="-----------------------------------\n-- ID: 5688\n-- Item: Head of Grauberg Lettuce\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/head_of_isleracea.lua"]={["Path"]="scripts/items/head_of_isleracea.lua",["SHA256"]="ae134e5b00217aee1154fcc0559a06c78aece9efd73d678476c6cd589569433c",["Text"]="-----------------------------------\n-- ID: 5965\n-- Item: Head of Isleracea\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- Agility 2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/head_of_napa.lua"]={["Path"]="scripts/items/head_of_napa.lua",["SHA256"]="bea090d9cb6ff23d2b04e72f71b908a79bc34a694ee989a39a504ea1371af76e",["Text"]="-----------------------------------\n-- ID: 5235\n-- Item: head_of_napa\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/healing_feather.lua"]={["Path"]="scripts/items/healing_feather.lua",["SHA256"]="f34f2c238c861343281d34c3d65c6392a266ffd435ff24f63250dbf65060d2a8",["Text"]="-----------------------------------\n-- ID: 18239\n-- Item: Healing Feather\n-- Item Effect: Cure Potency +15%\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10079.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HEALING_FEATHER) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HEALING_FEATHER)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HEALING_FEATHER })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.CURE_POTENCY, 15)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HEALING_FEATHER)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/healing_harness.lua"]={["Path"]="scripts/items/healing_harness.lua",["SHA256"]="0331198459102893a3f504285adb2482861869383d4c212bf4830361dbf7fb3e",["Text"]="-----------------------------------\n-- ID: 14495\n-- Item: Healing Harness\n-- Item Effect: Restores 50-75 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = math.randomInt(50, 75)\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"}};
